sample:
// console.log は ( ) の中身を画面に表示します
console.log("こんにちは、JavaScript！");

// ' と " はどちらも使えます(この教材では " で統一します)
console.log('シングルクォートでも同じです');

// カンマで区切ると、スペース区切りで並べて表示されます
console.log("好きな言語:", "JavaScript");

// Python:     print("ようこそ")
// JavaScript: console.log("ようこそ");
console.log("ようこそ");

